        return x

class Solution:
    def smallestNumber(self, n: int) -> int:
        x = 1
        while x < n and x < 511:
            x = x * 2 + 1
        return x

class Solution:
    def smallestNumber(self, n: int) -> int:
        x = 1
        while x < n - 1:
            x = x * 2 + 1
        return x
